  if (!value) return null;

  const normalized = value.replace(/-/g, "_").toUpperCase();

  if (normalized === "INSTITUTION" || normalized === "SCHOOL") return "institution";
  if (normalized === "INSTRUCTOR" || normalized === "TEACHER") return "teacher";
  if (normalized === "ADMIN") return "admin";

  return null;
}

export function normalizeStatus(status: unknown): ApplicationStatus {
  const value = readString(status)?.replace(/-/g, "_").toLowerCase();

  if (
    !value ||
    value === "none" ||
    value === "deactivated" ||
    value === "incomplete" ||
    value === "not_completed" ||
    value === "not_started"
  ) {
    return "none";
  }
  if (
    value === "pending" ||
    value === "pending_approval" ||
    value === "pending_review" ||
    value === "requires_info" ||
    value === "under_review"
  ) {
    return "pending_review";
  }
  if (value === "approved" || value === "verified" || value === "active") return "approved";
  if (value === "rejected" || value === "declined") return "rejected";
  if (value === "suspended" || value === "disabled") return "suspended";

  return "none";
}

export function normalizeAuthUser(payload: unknown): AuthUser {
  const user = readUserPayload(payload);
  const email = readString(user.email);
  const id = readString(user.id) ?? readString(user.userId) ?? readString(user.sub);

  if (!id || !email) {
    throw new Error("Backend auth user is missing id or email.");
  }

  return {
    applicationStatus: normalizeStatus(
      user.accountStatus ?? user.applicationStatus ?? user.verificationStatus ?? user.onboardingStatus,
    ),
    email,
    emailVerified: readBoolean(user.emailVerified ?? user.isEmailVerified) ?? false,
    id,
    instructorProfileId:
      readString(user.instructorProfileId) ??
      readString(user.instructorProfileID) ??
      readString(user.instructorId) ??
      (isRecord(user.instructorProfile) ? readString(user.instructorProfile.id) : undefined),
    institutionProfileId:
      readString(user.institutionProfileId) ??
      readString(user.institutionProfileID) ??
      readString(user.institutionId) ??
      (isRecord(user.institutionProfile) ? readString(user.institutionProfile.id) : undefined),
    name: readString(user.name) ?? readString(user.fullName) ?? null,
    phone: normalizeStoredUkPhone(user.phone),
    phoneVerified: readBoolean(user.phoneVerified) ?? false,
    role: normalizeRole(user.role),
  };
}

function normalizeAuthResponse(payload: unknown): BackendAuthResponse {
  const response = isRecord(payload) ? payload : {};
  const user = normalizeAuthUser(readUserPayload(response));
  const { accessToken, refreshToken } = readTokenPair(response);
  const expiresInMinutes =
    readNumber(response.expiresInMinutes) ??
    readNumber(response.emailVerificationExpiresInMinutes) ??
    readNumber(response.otpExpiresInMinutes);

  return {
    accessToken,
    accessTokenExpiresAt: readAccessTokenExpiresAt(response, accessToken),
    expiresInMinutes,
    otpToken: readString(response.otpToken),
    refreshToken,
    user,
  };
}

function normalizeTwoFactorChallenge(payload: unknown, fallbackEmail: string): TwoFactorLoginChallenge | null {
  const response = isRecord(payload) ? payload : {};
  const twoFactorRequired = readBoolean(response.twoFactorRequired);

  if (twoFactorRequired !== true) return null;

  const twoFactorToken = readString(response.twoFactorToken);
  if (!twoFactorToken) {
    throw new Error("Two-factor authentication is required, but the backend did not return a challenge token.");
  }

  return {
    code: "TWO_FACTOR_REQUIRED",
    email: fallbackEmail,
    expiresInMinutes: readNumber(response.expiresInMinutes),
    twoFactorRequired: true,
    twoFactorToken,
  };
}

function normalizeLoginResponse(payload: unknown, fallbackEmail: string): BackendAuthResponse | TwoFactorLoginChallenge {
  return normalizeTwoFactorChallenge(payload, fallbackEmail) ?? normalizeAuthResponse(payload);
}

function normalizeEmailVerificationChallenge(payload: unknown, fallbackEmail: string): EmailVerificationChallenge {
  const response = isRecord(payload) ? payload : {};
  const user = readOptionalUserPayload(response);
  const email = readString(response.email) ?? readString(user.email) ?? fallbackEmail;
  const backendCode = readString(response.code);
  const passwordUpdated = readBoolean(response.passwordUpdated);
  const expiresInMinutes =
    readNumber(response.expiresInMinutes) ??
    readNumber(response.emailVerificationExpiresInMinutes) ??
    readNumber(response.otpExpiresInMinutes);

  return {
    code: backendCode === "EMAIL_VERIFICATION_PENDING" ? "EMAIL_VERIFICATION_PENDING" : "EMAIL_VERIFICATION_REQUIRED",
    email,
    emailVerified: false,
    expiresInMinutes,
    message: readString(response.message),
    otpToken: readString(response.otpToken),
    passwordUpdated,
  };
}

function normalizeEmailVerificationResendResponse(
  payload: unknown,
  fallbackEmail: string,
): EmailVerificationResendResponse {
  const response = isRecord(payload) ? payload : {};
  const user = readOptionalUserPayload(response);

  return {
    code: readString(response.code),
    email: readString(response.email) ?? readString(user.email) ?? fallbackEmail,
    emailVerified: readBoolean(response.emailVerified ?? user.emailVerified) ?? false,
    expiresInMinutes:
      readNumber(response.expiresInMinutes) ??
      readNumber(response.emailVerificationExpiresInMinutes) ??
      readNumber(response.otpExpiresInMinutes),
    message: readString(response.message),
    otpToken: readString(response.otpToken),
  };
}

function normalizePasswordResetChallenge(payload: unknown): PasswordResetChallenge {
  const response = isRecord(payload) ? payload : {};

  return {
    expiresInMinutes:
      readNumber(response.expiresInMinutes) ??
      readNumber(response.passwordResetExpiresInMinutes) ??
      readNumber(response.otpExpiresInMinutes),
    otpToken: readString(response.otpToken),
  };
}

export async function createEmailAccount(input: SignupInput): Promise<EmailVerificationChallenge> {
  if (!input || !validateEmail(input.email) || !["teacher", "institution"].includes(input.role ?? "")) throw new Error("Use a valid email and account type.");
  if (!validatePassword(input.password)) throw new Error(passwordRequirementsMessage);
  input = { ...input, email: normalizeEmail(input.email) };
  const payload = {
    email: input.email,
    password: input.password,
    role: toBackendRole(input.role),
  };

  logBackendPayload(`POST ${backendAuthEndpoints.register}`, payload);

  if (backendEnabled()) {
    return normalizeEmailVerificationChallenge(
      await api.post<unknown>(backendAuthEndpoints.register, payload, { auth: false }),
      input.email,
    );
  }

  return {
    code: "EMAIL_VERIFICATION_REQUIRED",
    email: input.email,
    emailVerified: false,
  };
}

export async function loginWithEmail(input: LoginInput): Promise<BackendAuthResponse | TwoFactorLoginChallenge> {
  if (!input || !validateEmail(input.email) || typeof input.password !== "string" || input.password.length < 8 || input.password.length > 128) throw new Error("Use a valid email and a password between 8 and 128 characters.");
  input = { ...input, email: normalizeEmail(input.email) };
  logBackendPayload(`POST ${backendAuthEndpoints.login}`, {
    email: input.email,
    password: input.password,
  });

  if (backendEnabled()) {
    const response = normalizeLoginResponse(await api.post<unknown>(backendAuthEndpoints.login, input, { auth: false }), input.email);
    if (!("twoFactorRequired" in response)) logLoginUserData(response);
    return response;
  }

  const response = {
    user: mockUser(input.email),
  };
  logLoginUserData(response);
  return response;
}

export async function verifyEmail(input: EmailVerificationInput): Promise<BackendAuthResponse | TwoFactorLoginChallenge> {
  if (!input || typeof input.code !== "string" || !validateOtpCode(input.code) || !validateEmail(input.email)) throw new Error("Enter a valid email and 6-digit verification code.");
  const payload = {
    otp: input.code,
  };

  logBackendPayload(`POST ${backendAuthEndpoints.verifyEmail}`, {
    ...payload,
    otpToken: input.otpToken,
  });

  if (backendEnabled()) {
    if (!input.otpToken) {
      throw new Error("Request a new verification code before verifying this email.");
    }

    return normalizeLoginResponse(
      await api.post<unknown>(backendAuthEndpoints.verifyEmail, payload, {
        auth: false,
        headers: { Authorization: `Bearer ${input.otpToken}` },
      }),
      input.email,
    );
  }

  return {
    user: mockUser(input.email),
  };
}

export async function verifyTwoFactorLogin(input: TwoFactorVerificationInput): Promise<BackendAuthResponse> {
  if (!input || typeof input.code !== "string" || !validateTwoFactorCode(input.code)) throw new Error("Enter a valid authenticator or recovery code.");
  const payload = {
    code: input.code,
  };

  logBackendPayload(`POST ${backendAuthEndpoints.verifyTwoFactor}`, {
    ...payload,
    twoFactorToken: input.twoFactorToken,
  });

  if (backendEnabled()) {
    if (!input.twoFactorToken) {
      throw new Error("Sign in again before entering your two-factor code.");
    }

    const response = normalizeAuthResponse(
      await api.post<unknown>(backendAuthEndpoints.verifyTwoFactor, payload, {
        auth: false,
        headers: { Authorization: `Bearer ${input.twoFactorToken}` },
      }),
    );
    logLoginUserData(response);
    return response;
  }

  return {
    user: mockUser(input.email ?? "local-user@supplyed.local"),
  };
}

export async function resendEmailVerification(input: ResendEmailVerificationInput): Promise<EmailVerificationResendResponse> {
  if (!input || !validateEmail(input.email)) throw new Error("Use a valid email address.");
  input = { ...input, email: normalizeEmail(input.email) };
  logBackendPayload(`POST ${backendAuthEndpoints.resendEmailVerification}`, {
    email: input.email,
  });

  if (backendEnabled()) {
    return normalizeEmailVerificationResendResponse(
      await api.post<unknown>(backendAuthEndpoints.resendEmailVerification, input, { auth: false }),
      input.email,
    );
  }

  return {
    email: input.email,
    emailVerified: false,
  };
}

export async function requestPasswordReset(input: ForgotPasswordInput): Promise<PasswordResetChallenge> {
  if (!input || !validateEmail(input.email)) throw new Error("Use a valid email address.");
  input = { ...input, email: normalizeEmail(input.email) };
  logBackendPayload(`POST ${backendAuthEndpoints.forgotPassword}`, {
    email: input.email,
  });

  if (backendEnabled()) {
    return normalizePasswordResetChallenge(
      await api.post<unknown>(backendAuthEndpoints.forgotPassword, input, { auth: false }),
    );
  }

  return {
    expiresInMinutes: 10,
    otpToken: "local-password-reset-token",
  };
}

export async function resetPassword(input: PasswordResetInput): Promise<PasswordResetResponse> {
  if (!input || typeof input.code !== "string" || !validateOtpCode(input.code)) throw new Error("Enter the 6-digit reset code.");
  if (!validatePassword(input.password)) throw new Error(passwordRequirementsMessage);
  const payload = {
    otp: input.code,
    password: input.password,
  };

  logBackendPayload(`POST ${backendAuthEndpoints.resetPassword}`, {
    ...payload,
    otpToken: input.otpToken,
  });

  if (backendEnabled()) {
    if (!input.otpToken) {
      throw new Error("Request a new reset code before changing your password.");
    }

    const response = await api.post<unknown>(backendAuthEndpoints.resetPassword, payload, {
      auth: false,
      headers: { Authorization: `Bearer ${input.otpToken}` },
    });

    const record = isRecord(response) ? response : {};

    return {
      passwordReset: readBoolean(record.passwordReset) ?? true,
    };
  }

  return { passwordReset: true };
}

export async function exchangeOAuthAccount(input: OAuthBackendInput): Promise<BackendAuthResponse> {
  logBackendPayload(`POST ${backendAuthEndpoints.oauthGoogle}`, {
    email: input.email,
    image: input.image,
    name: input.name,
    provider: input.provider,
    providerAccountId: input.providerAccountId,
    providerAccessToken: input.providerAccessToken,
    providerIdToken: input.providerIdToken,
  });

  if (backendEnabled()) {
    if (!backendOAuthExchangeEnabled()) {
      throw new Error("Social sign-in is not available yet. Use email and password while we finish connecting Google sign-in.");
    }

    if (input.provider !== "google") {
      throw new Error("Microsoft sign-in is not connected to the SupplyED backend yet.");
    }

    if (!input.providerIdToken) {
      throw new Error("Google did not return an ID token for backend sign-in.");
    }

    const response = normalizeLoginResponse(
      await api.post<unknown>(backendAuthEndpoints.oauthGoogle, { credential: input.providerIdToken, role: toBackendRole(input.role) }, { auth: false }),
      input.email,
    );

    if ("twoFactorRequired" in response) {
      throw new Error("This account has two-factor authentication enabled. Sign in with email and password to enter your security code.");
    }

    return response;
  }

  return {
    user: mockUser(input.email, {
      emailVerified: true,
    }),
  };
}

export async function refreshBackendAuth(refreshToken: string): Promise<BackendAuthResponse | null> {
  logBackendPayload(`POST ${backendAuthEndpoints.refresh}`, {
    refreshToken,
  });

  if (!backendEnabled()) return null;

  return normalizeAuthResponse(await api.post<unknown>(backendAuthEndpoints.refresh, { refreshToken }, { auth: false }));
}

features/auth/actions.ts.before:
"use server";

import { actionError, actionOk } from "@/lib/server/action-response";
import { signIn } from "@/auth";
import { getAuthenticatedEntryHref } from "@/lib/routes";
import { api, ApiError } from "@/lib/server/api-client";
import { getDocumentState } from "@/features/onboarding/documents";
import { missingRequiredDocuments } from "@/features/onboarding/document-utils";
import { getServerAuthContext } from "@/lib/server/auth-context";
import type { AppRole, ApplicationStatus } from "@/types/supplyed";

import {
  createEmailAccount,
  loginWithEmail,
  normalizeRole,
  normalizeStatus,
  refreshBackendAuth,
  requestPasswordReset,
  resendEmailVerification,
  resetPassword,
  verifyEmail,
  verifyTwoFactorLogin,
} from "./backend";
import {
  parseEmailVerificationForm,
  parseForgotPasswordForm,
  parseLoginForm,
  parsePasswordResetForm,
  parseResendEmailVerificationForm,
  parseSignupForm,
  parseTwoFactorForm,
  passwordRequirementsMessage,
  validateEmail,
  validatePassword,
} from "./schemas";
import { createVerifiedEmailSessionTicket } from "./session-ticket";
import type { BackendAuthResponse, EmailVerificationResendResponse, TwoFactorLoginChallenge } from "./types";

async function createVerifiedSessionPayload(response: BackendAuthResponse) {
  const role = normalizeRole(response.user.role);
  const applicationStatus = await readProfileApplicationStatus(role, response.accessToken);
  const sessionResponse: BackendAuthResponse = {
    ...response,
    user: {
      ...response.user,
      applicationStatus,
      role,
    },
  };

  return {
    nextHref: getAuthenticatedEntryHref({ applicationStatus, role }),
    ticket: createVerifiedEmailSessionTicket(sessionResponse),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function readString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value : undefined;
}

function readApiErrorText(error: ApiError) {
  const message = isRecord(error.payload) ? error.payload.message : undefined;

  if (Array.isArray(message)) return message.filter((item): item is string => typeof item === "string").join(" ");
  if (typeof message === "string") return message;

  return error.message;
}

function readApiErrorCode(error: ApiError) {
  if (!isRecord(error.payload)) return undefined;

  return readString(error.payload.code) ?? readString(error.payload.error);
}

function buildBearerHeaders(accessToken: string) {
  return { Authorization: `Bearer ${accessToken}` };
}

async function readProfileApplicationStatus(role: AppRole | null, accessToken?: string | null): Promise<ApplicationStatus> {
  if (!accessToken) return "none";

  const profilePath =
    role === "teacher" ? "/instructors/me" : role === "institution" ? "/institutions/me" : null;

  if (!profilePath) return "none";

  try {
    const profile = await api.get<unknown>(profilePath, {
      auth: false,
      cache: "no-store",
      headers: buildBearerHeaders(accessToken),
    });

    const status = normalizeStatus(isRecord(profile) ? profile.status : undefined);
    if (status === "suspended") return status;
    if (status === "none" || status === "rejected") return "none";

    const documents = await getDocumentState(role, { accessToken });
    if (missingRequiredDocuments(documents.documentRequirements, documents.documents).length > 0) return "none";
    return status;
  } catch (error) {
    if (error instanceof ApiError && (error.status === 403 || error.status === 404)) return "none";
    throw error;
  }
}

function isRegisteredEmailError(error: unknown) {
  if (!(error instanceof ApiError)) return false;

  const code = readApiErrorCode(error);
  const text = readApiErrorText(error);

  return (
    code === "EMAIL_ALREADY_REGISTERED" ||
    code === "EMAIL_VERIFICATION_PENDING" ||
    code === "EMAIL_VERIFICATION_REQUIRED" ||
    (error.status === 409 && /email .*already registered|already registered/i.test(text))
  );
}

function isEmailNotVerifiedError(error: unknown) {
  if (!(error instanceof ApiError)) return false;

  const code = readApiErrorCode(error);
  const text = readApiErrorText(error);

  return (
    code === "EMAIL_NOT_VERIFIED" ||
    code === "EMAIL_VERIFICATION_PENDING" ||
    code === "EMAIL_VERIFICATION_REQUIRED" ||
    (error.status === 403 && /email .*not verified|verify your email|email verification/i.test(text))
  );
}

function emailVerificationChallengeFromResponse(
  response: BackendAuthResponse | EmailVerificationResendResponse,
  fallbackEmail: string,
  message?: string,
) {
  const email = "user" in response ? response.user.email : response.email;

  return {
    code: "EMAIL_VERIFICATION_REQUIRED" as const,
    email: email || fallbackEmail,
    emailVerified: false as const,
    expiresInMinutes: response.expiresInMinutes,
    message,
    otpToken: response.otpToken,
  };
}

function isTwoFactorChallenge(response: BackendAuthResponse | TwoFactorLoginChallenge): response is TwoFactorLoginChallenge {
  return "twoFactorRequired" in response && response.twoFactorRequired === true;
}

async function issueLoginVerificationChallenge(email: string, message: string) {
  const resend = await resendEmailVerification({ email });

  if (resend.emailVerified) {
    return actionError("This email is already verified. Log in again to continue.", {
      code: "EMAIL_ALREADY_VERIFIED",
    });
  }

  return actionOk(emailVerificationChallengeFromResponse(resend, email, resend.message), message);
}

function toAuthActionError(error: unknown, fallback = "We could not complete that auth request.") {
  if (error instanceof ApiError) {
    return actionError(error.message || fallback);
  }

  if (error instanceof Error && error.message) {
    return actionError(error.message);
  }

  return actionError(fallback);
}

export async function loginWithEmailAction(_previousState: unknown, formData: FormData) {
  const input = parseLoginForm(formData);

  if (!validateEmail(input.email)) {
    return actionError("Use a valid email address.", {
      fieldErrors: { email: "Use a valid email address." },
    });
  }

  if (input.password.length < 8 || input.password.length > 128) {
    return actionError("Password must be between 8 and 128 characters.", {
      fieldErrors: { password: "Password must be between 8 and 128 characters." },
    });
  }

  try {
    const response = await loginWithEmail(input);

    if (isTwoFactorChallenge(response)) {
      return actionOk(response, "Enter your authenticator or recovery code to finish signing in.");
    }

    if (!response.user.emailVerified) {
      return actionOk(
        emailVerificationChallengeFromResponse(
          response,
          input.email,
          "Your email is not verified yet. We sent a new verification code.",
        ),
        "Your email is not verified yet. We sent a new verification code.",
      );
    }

    return actionOk(await createVerifiedSessionPayload(response), "Credentials accepted.");
  } catch (error) {
    if (isEmailNotVerifiedError(error)) {
      try {
        return await issueLoginVerificationChallenge(
          input.email,
          "Your email is not verified yet. We sent a new verification code.",
        );
      } catch (resendError) {
        return toAuthActionError(resendError, "Your email is not verified. We could not send a new code.");
      }
    }

    return toAuthActionError(error, "We could not sign you in with those details.");
  }
}

export async function verifyTwoFactorLoginAction(_previousState: unknown, formData: FormData) {
  const input = parseTwoFactorForm(formData);

  if (!input.twoFactorToken) {
    return actionError("Sign in again before entering your two-factor code.", {
      fieldErrors: { code: "Sign in again before entering your two-factor code." },
    });
  }

  if (!/^(?:\d{6}|[A-HJ-NP-Z2-9]{4}(?:-[A-HJ-NP-Z2-9]{4}){3})$/i.test(input.code)) {
    return actionError("Enter a 6-digit authenticator code or a valid recovery code.", {
      fieldErrors: { code: "Enter a 6-digit authenticator code or a valid recovery code." },
    });
  }

  try {
    const response = await verifyTwoFactorLogin(input);

    return actionOk(await createVerifiedSessionPayload(response), "Two-factor authentication verified.");
  } catch (error) {
    return toAuthActionError(error, "We could not verify that two-factor code.");
  }
}

export async function signupWithEmailAction(_previousState: unknown, formData: FormData) {
  const input = parseSignupForm(formData);

  if (formData.get("termsAccepted") !== "on") {
    return actionError("Accept the terms and privacy policy before creating your account.", {
      fieldErrors: { termsAccepted: "Accept the terms and privacy policy to continue." },
    });
  }

  if (input.role !== "teacher" && input.role !== "institution") {
    return actionError("Choose whether you are signing up as a teacher or a school.", {
      fieldErrors: { role: "Choose an account type." },
    });
  }

  if (!validateEmail(input.email)) {
    return actionError("Use a valid email address.", {
      fieldErrors: { email: "Use a valid email address." },
    });
  }

  if (!validatePassword(input.password)) {
    return actionError(passwordRequirementsMessage, {
      fieldErrors: { password: passwordRequirementsMessage },
    });
  }

  try {
    const challenge = await createEmailAccount(input);
    return actionOk(challenge, challenge.message ?? "Account created. Verify your email to continue.");
  } catch (error) {
    if (isRegisteredEmailError(error)) {
      try {
        const resend = await resendEmailVerification({ email: input.email });

        if (!resend.emailVerified) {
          return actionOk(
            {
              code: "EMAIL_VERIFICATION_PENDING" as const,
              email: resend.email,
              emailVerified: false as const,
              expiresInMinutes: resend.expiresInMinutes,
              message: resend.message,
              otpToken: resend.otpToken,
              passwordUpdated: false,
            },
            "This email already has a pending signup. We sent a new code. Use the password from your first signup attempt after verifying.",
          );
        }

        return actionError("This email is already registered. Log in instead.", {
          code: "EMAIL_ALREADY_REGISTERED",
          fieldErrors: { email: "This email is already registered. Log in instead." },
        });
      } catch (resendError) {
        return toAuthActionError(resendError, "This email is already registered. Log in or request a new code.");
      }
    }

    if (error instanceof ApiError && error.status >= 500) {
      return actionError("We could not finish signup. Please try again with the same email and password; your account may already have been saved.");
    }

    return toAuthActionError(error, "We could not create this account.");
  }
}

export async function forgotPasswordAction(_previousState: unknown, formData: FormData) {
  const input = parseForgotPasswordForm(formData);

  if (!validateEmail(input.email)) {
    return actionError("Use a valid email address.", {
      fieldErrors: { email: "Use a valid email address." },
    });
  }

  try {
    const challenge = await requestPasswordReset(input);
    return actionOk(challenge, "Check your email for a 6-digit reset code. If this address is registered, it should arrive shortly.");
  } catch (error) {
    return toAuthActionError(error, "We could not request a password reset.");
  }
}

export async function resetPasswordAction(_previousState: unknown, formData: FormData) {
  const input = parsePasswordResetForm(formData);

  if (!/^\d{6}$/.test(input.code)) {
    return actionError("Enter the 6-digit reset code.", {
      fieldErrors: { code: "Enter the 6-digit reset code." },
    });
  }

  if (!validatePassword(input.password)) {
    return actionError(passwordRequirementsMessage, {
      fieldErrors: { password: passwordRequirementsMessage },
    });
  }

  if (!input.otpToken) {
    return actionError("Request a new reset code before changing your password.", {
      fieldErrors: { code: "Request a new reset code before changing your password." },
    });
  }

  try {
    return actionOk(await resetPassword(input), "Password reset successfully. Log in with your new password.");
  } catch (error) {
    return toAuthActionError(error, "We could not reset your password.");
  }
}

export async function verifyEmailAction(_previousState: unknown, formData: FormData) {
  const input = parseEmailVerificationForm(formData);

  if (!validateEmail(input.email)) {
    return actionError("Use a valid email address.", {
      fieldErrors: { email: "Use a valid email address." },
    });
  }

  if (!/^\d{6}$/.test(input.code)) {
    return actionError("Enter the 6-digit verification code.", {
      fieldErrors: { code: "Enter the 6-digit verification code." },
    });
  }

  if (!input.otpToken) {
    return actionError("Request a new verification code before verifying this email.", {
      fieldErrors: { code: "Request a new verification code before verifying this email." },
    });
  }

  try {
    return actionOk(await verifyEmail(input), "Email verified.");
  } catch (error) {
    return toAuthActionError(error, "We could not verify that code.");
  }
}

export async function verifyEmailSessionAction(_previousState: unknown, formData: FormData) {
  const input = parseEmailVerificationForm(formData);

  if (!validateEmail(input.email)) {
    return actionError("Use a valid email address.", {
      fieldErrors: { email: "Use a valid email address." },
    });
