type SignupStage = "account" | "verify" | "two-factor";

function socialUnavailableMessage(provider: "google" | "microsoft-entra-id") {
  return provider === "google"
    ? "Google sign-in is not configured. Add AUTH_GOOGLE_ID and AUTH_GOOGLE_SECRET, then restart the app."
    : "Microsoft sign-in is not configured. Add AUTH_MICROSOFT_ENTRA_ID_ID and AUTH_MICROSOFT_ENTRA_ID_SECRET, then restart the app.";
}

function isSocialProviderAvailable(provider: "google" | "microsoft-entra-id", socialAuth: SocialAuthAvailability) {
  return provider === "google" ? socialAuth.google : socialAuth.microsoft;
}

function SignupRouteClientInner({
  foundingSignupEmail,
  foundingSignupType,
  initialError,
  socialAuth,
}: {
  foundingSignupEmail?: string;
  foundingSignupType?: FoundingSignupType;
  initialError?: string;
  socialAuth: SocialAuthAvailability;
}) {
  const router = useRouter();
  const [foundingIntent] = useState(() => {
    const storedIntent = readFoundingSignupIntent(foundingSignupType);
    if (storedIntent) return storedIntent;

    if (foundingSignupType && foundingSignupEmail) {
      return saveFoundingSignupIntent({
        email: foundingSignupEmail,
        type: foundingSignupType,
      });
    }

    return null;
  });
  const foundingEmail = foundingIntent?.email ?? foundingSignupEmail;
  const [stage, setStage] = useState<SignupStage>("account");
  const [signupEmail, setSignupEmail] = useState("");
  const [verificationNotice, setVerificationNotice] = useState<string>();
  const [verificationToken, setVerificationToken] = useState<string>();
  const [twoFactor, setTwoFactor] = useState<TwoFactorLoginChallenge>();
  const [twoFactorExpiresAt, setTwoFactorExpiresAt] = useState<number>();
  const [resendAvailableAt, setResendAvailableAt] = useState<number>();
  const { authToasts, dismissAuthToast, showAuthError } = useAuthToasts(initialError);

  function formData(values: Record<string, string>) {
    const data = new FormData();
    Object.entries(values).forEach(([key, value]) => data.set(key, value));
    return data;
  }

  async function startVerification(email: string, password: string, role: string, termsAccepted: boolean) {
    let result: Awaited<ReturnType<typeof signupAction>>;

    try {
      result = await signupAction(null, formData({ email, password, role, termsAccepted: termsAccepted ? "on" : "" }));
    } catch (error) {
      const message = readUnknownAuthErrorMessage(error, "We could not create this account.");
      showAuthError(message);
      return { message, ok: false as const };
    }

    if (!result.ok) {
      showAuthError(result.message);
      return {
        fieldErrors: result.fieldErrors,
        message: result.message,
        ok: false as const,
      };
    }

    const signupEmail = result.data.email || email;
    const passwordNotice = result.data.passwordUpdated === false ? result.message : undefined;
    setSignupEmail(signupEmail);
    setVerificationToken(result.data.otpToken);
    setVerificationNotice(passwordNotice);
    setResendAvailableAt(nextCodeResendAvailableAt());
    setStage("verify");
    return { ok: true as const };
  }

  function backToAccount() {
    setTwoFactor(undefined);
    setTwoFactorExpiresAt(undefined);
    setSignupEmail("");
    setVerificationToken(undefined);
    setVerificationNotice(undefined);
    setResendAvailableAt(undefined);
    setStage("account");
  }

  async function finishVerification(code: string, verifyTwoFactor = false) {
    let verificationResult: Awaited<ReturnType<typeof verifySignupEmail>> | Awaited<ReturnType<typeof verifySignupTwoFactor>>;

    try {
      verificationResult = verifyTwoFactor
        ? await verifySignupTwoFactor(null, formData({ code, email: signupEmail, twoFactorToken: twoFactor?.twoFactorToken ?? "" }))
        : await verifySignupEmail(null, formData({ code, email: signupEmail, otpToken: verificationToken ?? "" }));
    } catch (error) {
      const message = readUnknownAuthErrorMessage(error, "We could not verify that code.");
      showAuthError(message);
      return { message, ok: false as const };
    }

    if (!verificationResult.ok) {
      showAuthError(verificationResult.message);
      return {
        message: verificationResult.message,
        ok: false as const,
      };
    }

    if ("twoFactorRequired" in verificationResult.data && verificationResult.data.twoFactorRequired) {
      const challenge = verificationResult.data;
      setTwoFactor(challenge);
      setTwoFactorExpiresAt(
        typeof challenge.expiresInMinutes === "number" && Number.isFinite(challenge.expiresInMinutes) && challenge.expiresInMinutes > 0
          ? Date.now() + challenge.expiresInMinutes * 60 * 1000
          : undefined,
      );
      setVerificationToken(undefined);
      setStage("two-factor");
      return { ok: true as const };
    }

    const sessionPayload = readAuthSessionTicketPayload(verificationResult.data);
    if (!sessionPayload) {
      const message = "Email verified, but we could not create your session. Log in again to continue.";
      showAuthError(message);
      return {
        message,
        ok: false as const,
      };
    }

    let signInResult: Awaited<ReturnType<typeof signIn>>;

    try {
      signInResult = await signIn("credentials", {
        flow: "verified-email-session",
        redirect: false,
        redirectTo: sessionPayload.nextHref,
        ticket: sessionPayload.ticket,
      });
    } catch (error) {
      const message = readUnknownAuthErrorMessage(error, "Email verified, but we could not create your session.");
      showAuthError(message);
      return { message, ok: false as const };
    }

    if (!signInResult?.ok) {
      const message = signInResult?.error || "Email verified, but we could not create your session. Log in again to continue.";
      showAuthError(message);
      return {
        message,
        ok: false as const,
      };
    }

    startRouteLoading();
    if (sessionPayload.nextHref !== "/onboarding") {
      clearFoundingSignupIntent();
    }
    router.replace(sessionPayload.nextHref);
    router.refresh();
    return { ok: true as const };
  }

