    try {
      result = await resendSignupVerification(null, formData({ email: signupEmail }));
    } catch (error) {
      const message = readUnknownAuthErrorMessage(error, "We could not resend the verification code.");
      showAuthError(message);
      return { message, ok: false as const };
    }

    if (!result.ok) {
      showAuthError(result.message);
      return {
        message: result.message,
        ok: false as const,
      };
    }

    if (!result.data.emailVerified) {
      setVerificationToken(result.data.otpToken);
      setVerificationNotice(result.message);
      setResendAvailableAt(nextCodeResendAvailableAt());
    }

    return { ok: true as const };
  }

  function goLanding() {
    startRouteLoading();
    router.push("/");
  }

  function goLogin() {
    startRouteLoading();
    router.push("/login");
  }

  function startSocialAuth(provider: "google" | "microsoft-entra-id") {
    if (!isSocialProviderAvailable(provider, socialAuth)) {
      showAuthError(socialUnavailableMessage(provider));
      return;
    }

    startRouteLoading();
    void signIn(provider, { redirectTo: "/post-auth?authSource=signup" }).catch((error) => {
      showAuthError(readUnknownAuthErrorMessage(error, "Social sign-up could not start."));
    });
  }

  if (stage === "account") {
    return (
      <>
        <SignupAccessPage
          foundingType={foundingIntent?.type ?? foundingSignupType}
          initialEmail={foundingEmail}
          onAccountCreated={startVerification}
          onGoogleAuth={() => startSocialAuth("google")}
          onLanding={goLanding}
          onLogin={goLogin}
          onMicrosoftAuth={() => startSocialAuth("microsoft-entra-id")}
          socialAuth={socialAuth}
        />
        <PublicThemeControls />
        <ToastStack autoCloseMs={7000} onDismiss={dismissAuthToast} toasts={authToasts} />
      </>
    );
  }

  if (stage === "verify") {
    return (
      <>
        <SignupVerifyPage
          email={signupEmail}
          notice={verificationNotice}
          onBack={backToAccount}
          onLanding={goLanding}
          onLogin={goLogin}
          onResend={resendVerification}
          onVerified={finishVerification}
          resendAvailableAt={resendAvailableAt}
        />
        <PublicThemeControls />
        <ToastStack autoCloseMs={7000} onDismiss={dismissAuthToast} toasts={authToasts} />
      </>
    );
  }

  if (stage === "two-factor" && twoFactor) {
    return (
      <>
        <TwoFactorChallengePage
          email={twoFactor.email}
          expiresAt={twoFactorExpiresAt}
          notice="Email verified. Complete two-factor verification to continue."
          onBack={goLogin}
          onLanding={goLanding}
          onVerified={(code) => finishVerification(code, true)}
        />
        <PublicThemeControls />
        <ToastStack autoCloseMs={7000} onDismiss={dismissAuthToast} toasts={authToasts} />
      </>
    );
  }

  return null;
}

export function SignupRouteClient({
  foundingSignupEmail,
  foundingSignupType,
  initialError,
  socialAuth,
